func TestOperatorEventReplayDispatchesCompleteCanonicalSnapshotParity(t *testing.T) {
	type fixture struct {
		store  completeOperatorReplayProofStore
		db     *sql.DB
		sqlite bool
	}
	routeShapes := []struct {
		name     string
		fanOut   bool
		envelope func(string, string) events.EventEnvelope
	}{
		{
			name: "singular_target",
			envelope: func(entityID, _ string) events.EventEnvelope {
				return events.EventEnvelope{
					EntityID: entityID, FlowInstance: "target-flow/instance", Scope: events.EventScopeEntity,
					Source: events.RouteIdentity{FlowID: "source-flow", FlowInstance: "source-flow/instance", EntityID: uuid.NewString()},
					Target: events.RouteIdentity{FlowID: "target-flow", FlowInstance: "target-flow/instance", EntityID: entityID},
				}
			},
		},
		{
			name:   "fan_out_target_set",
			fanOut: true,
			envelope: func(entityID, auditEntityID string) events.EventEnvelope {
				return events.EventEnvelope{
					Scope:  events.EventScopeGlobal,
					Source: events.RouteIdentity{FlowID: "source-flow", FlowInstance: "source-flow/instance", EntityID: uuid.NewString()},
					TargetSet: []events.RouteIdentity{
						{FlowID: "target-flow", FlowInstance: "target-flow/instance", EntityID: entityID},
						{FlowID: "audit-flow", FlowInstance: "audit-flow/instance", EntityID: auditEntityID},
					},
				}
			},
		},
	}
	for _, tc := range []struct {
		name string
		open func(*testing.T, context.Context) fixture
	}{
		{
			name: "sqlite",
			open: func(t *testing.T, ctx context.Context) fixture {
				sqliteStore := storetest.StartSQLiteRuntimeStoreWithContext(t, ctx)
				return fixture{store: sqliteStore, db: storetest.DatabaseForTest(sqliteStore), sqlite: true}
			},
		},
		{
			name: "postgres",
			open: func(t *testing.T, _ context.Context) fixture {
				_, db, cleanup := testutil.StartPostgres(t)
				t.Cleanup(cleanup)
				return fixture{store: storetest.AdmitPostgresRuntimeStore(t, db), db: db}
			},
		},
	} {
		for _, routeShape := range routeShapes {
			t.Run(tc.name+"/"+routeShape.name, func(t *testing.T) {
				ctx := testAuthorActivityContext(context.Background())
				f := tc.open(t, ctx)
				runID := uuid.NewString()
				bus, err := newScopedAPITestEventBus(t, f.store, runtimebus.EventBusOptions{
					ContractBundle: completeOperatorReplaySource(t),
				})
				if err != nil {
					t.Fatalf("NewEventBusWithOptions: %v", err)
				}
				const agentID = "complete-replay-agent"
				agentIdentity := runtimebustest.IdentityForRun(t, runID, agentID, "target-flow/instance")
				ch := subscribeOperatorReplayIdentity(t, bus, agentIdentity)
				defer runtimebustest.Unsubscribe(bus, agentID)

				parentID := uuid.NewString()
				originalID := uuid.NewString()
				entityID := uuid.NewString()
				auditEntityID := uuid.NewString()
				deliveryTarget := events.RouteIdentity{FlowID: "target-flow", FlowInstance: "target-flow/instance", EntityID: entityID}
				auditTarget := events.RouteIdentity{FlowID: "audit-flow", FlowInstance: "audit-flow/instance", EntityID: auditEntityID}
				createdAt := time.Unix(1700001300, 123456000).UTC()
				seedCompleteReplayRun(t, ctx, f.db, f.sqlite, runID, createdAt.Add(-time.Minute))
				envelope := routeShape.envelope(entityID, auditEntityID)
				if err := storetest.UpsertStaticAgentFixtureForSource(t, ctx, f.store, runtimemanager.PersistedAgent{
					Config: withAPITestIntent(t, runtimeactors.AgentConfig{
						Identity: agentIdentity, ID: agentID, Role: "observer",
						FlowID: "target-flow", FlowPath: agentIdentity.FlowInstance(), EntityID: entityID,
						Type: "stub", Model: "regular", ExecutionMode: "live", ResolvedLLMBackend: "anthropic", Config: []byte(`{}`), Subscriptions: []string{"scan.requested"},
					}),
					Status: "active", HiredBy: "test", StartedAt: createdAt,
				}, runStartTestSourceArtifactFact()); err != nil {
					t.Fatalf("UpsertAgent(%s): %v", agentID, err)
				}
				var auditCh <-chan *runtimebus.LocalDelivery
				auditIdentity := runtimebustest.IdentityForRun(t, runID, "complete-replay-auditor", "audit-flow/instance")
				if routeShape.fanOut {
					auditCh = subscribeOperatorReplayIdentity(t, bus, auditIdentity)
					defer runtimebustest.Unsubscribe(bus, auditIdentity.AgentID())
					if err := storetest.UpsertStaticAgentFixtureForSource(t, ctx, f.store, runtimemanager.PersistedAgent{
						Config: withAPITestIntent(t, runtimeactors.AgentConfig{
							Identity: auditIdentity, ID: auditIdentity.AgentID(), Role: "auditor",
							FlowID: "audit-flow", FlowPath: auditIdentity.FlowInstance(), EntityID: auditEntityID,
							Type: "stub", Model: "regular", ExecutionMode: "live", ResolvedLLMBackend: "anthropic", Config: []byte(`{}`), Subscriptions: []string{"scan.requested"},
						}),
						Status: "active", HiredBy: "test", StartedAt: createdAt,
					}, runStartTestSourceArtifactFact()); err != nil {
						t.Fatalf("UpsertAgent(%s): %v", auditIdentity.AgentID(), err)
					}
				}
				parent := eventtest.InExecutionMode(eventtest.PersistedRuntimeControlForProducer(
					parentID, events.EventType("filler.event"), eventtest.Producer(events.EventProducerPlatform, "replay-proof"), "parent-task",
					json.RawMessage(`{"parent":true}`), 0, runID, "", events.EventEnvelope{}, createdAt.Add(-time.Minute),
				), "mock")
				original := eventtest.InExecutionMode(eventtest.PersistedChildForProducer(
					originalID, events.EventType("source-flow/instance/scan.requested"), eventtest.Producer(events.EventProducerAgent, "origin-agent"), "event-owned-task",
					json.RawMessage("{\n  \"topic\": \"medicine\", \"score\": 1.0, \"task_id\": \"payload-owned-task\"\n}"), 4, runID, parentID, envelope, createdAt,
				), "mock")
				originalRoute := events.DeliveryRoute{Recipient: events.MustAgentDeliveryRecipient(agentID), AgentIdentity: agentIdentity, Target: events.MustExistingEntityTarget(deliveryTarget)}
				originalRoutes := []events.DeliveryRoute{originalRoute}
				if routeShape.fanOut {
					originalRoutes = append(originalRoutes, events.DeliveryRoute{
						Recipient: events.MustAgentDeliveryRecipient(auditIdentity.AgentID()), AgentIdentity: auditIdentity,
						Target: events.MustExistingEntityTarget(auditTarget),
					})
				}
				storetest.CommitSemanticEvent(t, ctx, f.store, parent)
				storetest.CommitSemanticEventWithRoutes(t, ctx, f.store, original,
					originalRoutes,
					runtimepipelineobligation.ScopeSubscribed)
				frameStore, ok := f.store.(storetest.ManagedAgentTurnFixtureStore)
				if !ok {
					t.Fatalf("%T does not support managed-turn replay proof", f.store)
				}
				sourceTurnID := uuid.NewString()
				sourceFrame := storetest.PersistManagedAgentTurnFixture(t, ctx, storetest.ManagedAgentTurnFixture{
					Store: frameStore, Selected: f.store, Identity: agentIdentity, RunID: runID,
					SessionID: uuid.NewString(), TurnID: sourceTurnID, Memory: agentmemory.Plan{Enabled: false},
					Event: original, DeliveryRoute: &originalRoute, DeliveryCommitted: true, ParseOK: true, CreatedAt: createdAt.Add(time.Minute), ExecutionMode: executionmode.Mock, Adapter: "mock_python",
				})
				for _, route := range originalRoutes {
					if route.Recipient.ID() == agentID {
						continue
					}
					markOperatorReplayDeliveryTerminal(t, ctx, f.store, f.db, f.sqlite, original, route)
				}
				persistedOriginal, err := f.store.LoadOperatorEvent(ctx, originalID)
				if err != nil {
					t.Fatalf("LoadOperatorEvent original: %v", err)
				}
				persistedOriginalSnapshot, err := persistedOriginal.EventSnapshot()
				if err != nil {
					t.Fatalf("EventSnapshot original: %v", err)
				}
				assertOperatorReplaySnapshot(t, persistedOriginalSnapshot, original)

				replayAt := createdAt.Add(2 * time.Minute)
				handler := completeOperatorReplayTestHandler(t, f.store, bus, replayAt)
				if _, err := updateCompleteReplayChainDepth(ctx, f.db, f.sqlite, originalID, -1); err == nil {
					t.Fatal("event schema admitted negative chain_depth")
				}
				dialect := authoractivityfixture.DialectPostgres
				if f.sqlite {
					dialect = authoractivityfixture.DialectSQLite
				}
				eventtestsql.CorruptEventStore(t, ctx, f.db, dialect, eventtestsql.EventCorruptionClaim{
					Invariant: "store.event_record.canonical_readback",
					Reason:    "prove operator replay rejects a durable target route that is valid JSON but not a route object",
				}, `UPDATE events SET target_route = ? WHERE event_id = ?`, `UPDATE events SET target_route = $1::jsonb WHERE event_id = $2::uuid`, `"bad"`, originalID)
				if _, err := f.store.LoadOperatorEvent(ctx, originalID); err == nil || !strings.Contains(err.Error(), "target_route") {
					t.Fatalf("canonical corrupt read error = %v, want target_route failure", err)
				}
				failed := rpcCall(t, handler, eventReplayBody(originalID, nil, "complete-corrupt-"+tc.name+"-"+routeShape.name))
				if failed.Error == nil {
					t.Fatal("corrupt event.replay error = nil")
				}
				assertNoReplayEvent(t, ch)
				if got := countOperatorReplayEvents(t, ctx, f.db); got != 2 {
					t.Fatalf("event rows after corrupt replay = %d, want parent+original", got)
				}

				targetRoute, err := json.Marshal(original.Envelope().Target)
				if err != nil {
					t.Fatalf("encode original target route: %v", err)
				}
				if err := updateCompleteReplayTargetRoute(ctx, f.db, f.sqlite, originalID, targetRoute); err != nil {
					t.Fatalf("restore original target route: %v", err)
				}
				response := rpcCall(t, handler, eventReplayBody(originalID, nil, "complete-success-"+tc.name+"-"+routeShape.name))
				if response.Error != nil {
					t.Fatalf("event.replay error = %#v", response.Error)
				}
				replayID := stringValue(t, asMap(t, response.Result)["replay_event_id"], "replay_event_id")
				persistedEnvelope := original.Envelope()
				if routeShape.fanOut {
					persistedEnvelope = events.EnvelopeForTargetSet(persistedEnvelope, []events.RouteIdentity{auditTarget, deliveryTarget})
				}
				persistedWant := eventtest.Replay(
					replayID, original.Type(), original.SourceAgent(), original.TaskID(), original.Payload(), original.ChainDepth()+1,
					events.EventLineage{RunID: runID, ParentEventID: originalID, TaskID: original.TaskID(), ExecutionMode: original.ExecutionMode()},
					persistedEnvelope, replayAt,
				)
				got := requireAPIV1RuntimeBusEvent(t, ch, "complete operator replay")
				deliveryWant := eventtest.Replay(
					replayID, original.Type(), original.SourceAgent(), original.TaskID(), original.Payload(), original.ChainDepth()+1,
					events.EventLineage{RunID: runID, ParentEventID: originalID, TaskID: original.TaskID(), ExecutionMode: original.ExecutionMode()},
					events.EnvelopeForTargetRoute(original.Envelope(), deliveryTarget), replayAt,
				)
				assertOperatorReplaySnapshot(t, got, deliveryWant)
				if routeShape.fanOut {
					auditGot := requireAPIV1RuntimeBusEvent(t, auditCh, "complete operator replay audit branch")
					auditWant := eventtest.Replay(
						replayID, original.Type(), original.SourceAgent(), original.TaskID(), original.Payload(), original.ChainDepth()+1,
						events.EventLineage{RunID: runID, ParentEventID: originalID, TaskID: original.TaskID(), ExecutionMode: original.ExecutionMode()},
						events.EnvelopeForTargetRoute(original.Envelope(), auditTarget), replayAt,
					)
					assertOperatorReplaySnapshot(t, auditGot, auditWant)
				}
				persisted, err := f.store.LoadOperatorEvent(ctx, replayID)
				if err != nil {
					t.Fatalf("LoadOperatorEvent replay: %v", err)
				}
				persistedSnapshot, err := persisted.EventSnapshot()
				if err != nil {
					t.Fatalf("EventSnapshot replay: %v", err)
				}
				assertOperatorReplaySnapshot(t, persistedSnapshot, persistedWant)
				var replayRoute events.DeliveryRoute
				for _, delivery := range persisted.Deliveries {
					if delivery.SubscriberID == agentID {
						replayRoute = delivery.Route.Normalized()
						break
					}
				}
				if replayRoute.Recipient.ID() != agentID {
					t.Fatalf("replay event is missing exact managed-agent route: %#v", persisted.Deliveries)
				}
				replayTurnID := uuid.NewString()
				replayFrame := storetest.PersistManagedAgentTurnFixture(t, ctx, storetest.ManagedAgentTurnFixture{
					Store: frameStore, Selected: f.store, Identity: agentIdentity, RunID: runID,
					SessionID: uuid.NewString(), TurnID: replayTurnID, Memory: agentmemory.Plan{Enabled: false},
					Event: persistedSnapshot, DeliveryRoute: &replayRoute, DeliveryCommitted: true, ParseOK: true, CreatedAt: replayAt.Add(time.Minute), ExecutionMode: executionmode.Mock, Adapter: "mock_python",
				})
				if sourceFrame.Frame.FrameID != "agent-frame:v1:"+sourceTurnID || replayFrame.Frame.FrameID != "agent-frame:v1:"+replayTurnID {
					t.Fatalf("replay frame occurrence IDs source=%q replay=%q", sourceFrame.Frame.FrameID, replayFrame.Frame.FrameID)
				}
				if sourceFrame.Frame.FrameID == replayFrame.Frame.FrameID || sourceFrame.Frame.ContentHash == replayFrame.Frame.ContentHash {
					t.Fatalf("public replay reused source frame identity: source=%#v replay=%#v", sourceFrame.Frame, replayFrame.Frame)
				}
			})
		}
	}
}

