				WorkOwner:           runtimeTestEventBusWorkOwner(t, bus),
				Module:              telegramConnectorSupportedSurfaceModule{source: source},
				Persistence:         workflowPersistence,
				RunLifecycle:        runLifecycle,
				DeliveryStore:       deliveryStore,
				PipelineObligations: pipelineObligations,
				Credentials:         credentialStore,
				ProviderCredentials: credentialStore,
				FlowRoutes:          bus,
				ChannelActivations:  replacementOwner,
			})

			stopActivityNode()
			coordinator = mismatchedCoordinator
			stopActivityNode = startConfiguredChannelActivityNode(t, ctx, coordinator, bus, db)
			mismatchedExecutor := configuredChannelExecutor(source, activationOwner, credentialStore, mismatchedCoordinator, mismatchedCoordinator)
			mismatchedCtx := configuredChannelCallContext(t, ctx, eventStore, actor, runID, entityID, flowInstance, "mismatched-plan-generation")
			if _, err := mismatchedExecutor.Execute(mismatchedCtx, "channel.ops.deliver", input); err == nil {
				t.Fatal("request executed through a private target carrying a different generation")
			}
			if calls.Load() != 2 {
				t.Fatalf("mismatched plan generation reached provider: calls=%d", calls.Load())
			}
			reloadedCoordinator := newExternalRuntimeTestPipelineCoordinator(t, bus, db, eventStore, runtimepipeline.PipelineCoordinatorOptions{
				WorkOwner:           runtimeTestEventBusWorkOwner(t, bus),
				Module:              telegramConnectorSupportedSurfaceModule{source: source},
				Persistence:         workflowPersistence,
				RunLifecycle:        runLifecycle,
				DeliveryStore:       deliveryStore,
				PipelineObligations: pipelineObligations,
				Credentials:         credentialStore,
				ProviderCredentials: credentialStore,
				FlowRoutes:          bus,
				ChannelActivations:  replacementOwner,
			})

			stopActivityNode()
			coordinator = reloadedCoordinator
			stopActivityNode = startConfiguredChannelActivityNode(t, ctx, coordinator, bus, db)
			staleExecutor := configuredChannelExecutor(source, activationOwner, credentialStore, reloadedCoordinator, reloadedCoordinator)
			staleCtx := configuredChannelCallContext(t, ctx, eventStore, actor, runID, entityID, flowInstance, "stale-plan-generation")
			if _, err := staleExecutor.Execute(staleCtx, "channel.ops.deliver", input); err == nil {
				t.Fatal("persisted old-generation request executed through replacement plan")
			}
			if calls.Load() != 2 {
				t.Fatalf("stale plan generation reached provider: calls=%d", calls.Load())
			}

			fencedOwner := testAdmittedChannelActivationOwner(t, credentialStore, binding)
			fencedCoordinator := newExternalRuntimeTestPipelineCoordinator(t, bus, db, eventStore, runtimepipeline.PipelineCoordinatorOptions{
				WorkOwner:           runtimeTestEventBusWorkOwner(t, bus),
				Module:              telegramConnectorSupportedSurfaceModule{source: source},
				Persistence:         workflowPersistence,
				RunLifecycle:        runLifecycle,
				DeliveryStore:       deliveryStore,
				PipelineObligations: pipelineObligations,
				Credentials:         credentialStore,
				ProviderCredentials: credentialStore,
				FlowRoutes:          bus,
				ChannelActivations:  fencedOwner,
			})
			stopActivityNode()
			coordinator = fencedCoordinator
			stopActivityNode = startConfiguredChannelActivityNode(t, ctx, coordinator, bus, db)
			fencedExecutor := configuredChannelExecutor(source, fencedOwner, credentialStore, fencedCoordinator, fencedCoordinator)
			fencedCtx := configuredChannelCallContext(t, ctx, eventStore, actor, runID, entityID, flowInstance, "replacement-fence")
			type executionResult struct {
				value any
				err   error
			}
			executed := make(chan executionResult, 1)
			dispatchFence.armed.Store(true)
			go func() {
				value, err := fencedExecutor.Execute(fencedCtx, "channel.ops.deliver", input)
				executed <- executionResult{value: value, err: err}
			}()
			select {
			case <-dispatchFence.started:
			case <-time.After(5 * time.Second):
				t.Fatal("durable channel activity did not reach the post-commit receiver fence")
			}
			replaced := make(chan error, 1)
			go func() {
				replaced <- fencedOwner.Replace(testAdmittedChannelActivationPublication(t, credentialStore, replacementBinding))
			}()
			deadline := time.Now().Add(time.Second)
			for {
				probe, open := fencedOwner.AcquireRuntimeOperation(binding.RuntimeToolID("deliver"))
				if open {
					probe.Release()
				} else {
					break
				}
				if time.Now().After(deadline) {
					t.Fatal("activation replacement did not fence new channel operations")
				}
				time.Sleep(time.Millisecond)
			}
			select {
			case err := <-replaced:
				t.Fatalf("activation replacement completed before admitted activity resumed: %v", err)
			default:
			}
			close(dispatchFence.release)
			select {
			case result := <-executed:
				if result.err != nil || !reflect.DeepEqual(result.value, wantResult) {
					t.Fatalf("predecessor activity across replacement fence = %#v, err=%v", result.value, result.err)
				}
			case <-time.After(5 * time.Second):
				t.Fatal("admitted predecessor activity did not settle")
			}
			if err := <-replaced; err != nil {
				t.Fatalf("replace channel activation: %v", err)
			}
			if calls.Load() != 3 {
				t.Fatalf("predecessor activity calls after replacement fence = %d, want three total distinct operations", calls.Load())
			}
			assertConfiguredChannelJournal(t, ctx, db, selected, runID, privateToolID, flowInstance, entityID, 6, 3)
			if err := fencedOwner.Replace(testAdmittedChannelActivationPublication(t, credentialStore, binding)); err != nil {
				t.Fatal(err)
			}
			proveRegisteredManagedChannelTransport(t, ctx, eventStore, fencedExecutor, fencedOwner, binding, actor, calls.Load)
		})
	}
}

